-- Bloque 6: Desayunos e Infusiones (23 registros).
-- Seed idempotente para Preview. Los registros permanecen inactivos en base.
begin;
on conflict (plato_id) do update set sinonimos=excluded.sinonimos, resumen=excluded.resumen, hack=excluded.hack, que_observar=excluded.que_observar, updated_at=now();
commit;
