insert into public.preview_catalogo_maestro_platos (plato_id, sinonimos, resumen, hack, que_observar, activo)
values
('alfajor', ARRAY['alfajor', 'alfajorcito', 'alfajor de dulce de leche', 'alfajor de maicena']::text[], 'Estructura de tapas tiernas unidas por un corazón generoso de dulce de leche, habitualmente bañado en chocolate o glasé. El monumento al dulce argentino.', 'Funciona perfecto como snack de energía rápida para deportistas o momentos de alto desgaste mental, pero es una bomba para un desayuno sedentario. Tip extra: si elegís uno, partilo a la mitad y comelo con un café negro sin azúcar; el contraste de sabores es perfecto y controlás la porción.', 'Registra la saciedad y el nivel de ansiedad por el dulce; los azúcares refinados combinados con dulce de leche suelen activar circuitos de recompensa que piden más dulce.', false),
('bizcochos-grasa', ARRAY['bizcochos con grasa', 'bizcochitos', 'bizcochos salados', 'hojaldraditos']::text[], 'Bocados crocantes de panadería a base de harina y grasa saturada. Palatabilidad extrema y alta densidad calórica.', 'Son un placer para acompañar el mate, pero por su perfil lipídico e industrial conviene moderar la porción estrictamente a un gusto ocasional. Tip extra: prioriza comerlos en compañía de una infusión amarga y sin abusar de la cantidad para evitar la pesadez matutina.', 'Nota la sed posterior y la pesadez en el pecho; las grasas de cocción pesada combinadas con harina refinada exigen un buen trago de agua para pasar.', false),
('bollo', ARRAY['bollo', 'bollitos', 'pan de leche', 'bollos dulces']::text[], 'Panificado dulce y esponjoso, elaborado con harinas refinadas, azúcar, leche y manteca. Aporte rápido de carbohidratos simples.', 'Al ser un producto de rápida asimilación, evitalo como única comida de la mañana si tenés una jornada exigente por delante. Tip extra: si podés untarlo con un toque de queso crema proteico o manteca de maní real, sumas grasas y proteínas que frenan el pico de azúcar.', 'Presta atención al hambre a media mañana; este tipo de panificado suele generar un rebote de apetito rápido.', false),
('cafe', ARRAY['cafe', 'café', 'cafecito', 'cafe solo', 'expreso']::text[], 'Estimulante natural por excelencia. Aporta cafeína que activa el sistema nervioso central, mejora el estado de alerta y moviliza la energía disponible.', 'Evitá sumarle azúcares refinados; si te cuesta amargo, un chorrito de leche o un toque de canela realzan el sabor. Tip extra: si sos sensible a la acidez estomacal, tomalo después de comer algo liviano y no en ayunas estrictas.', 'Registra tu nivel de foco y energía; nota si te aporta claridad o si te genera un pico de ansiedad o palpitaciones si tu tolerancia es baja.', false),
('cafe-con-leche', ARRAY['cafe con leche', 'café con leche', 'cortado', 'lágrima', 'submarino']::text[], 'El clásico desayuno rioplatense. Combina el estímulo del café con la densidad y saciedad de la leche, logrando un alimento líquido reconfortante.', 'Si buscás cuidar la glucemia, controlá la cantidad de azúcar agregada; el dulzor natural de la leche bien emulsionada suele ser suficiente. Tip extra: acompañalo con una fuente de proteína o grasa saludable si querés que la energía te dure hasta el almuerzo.', 'Registra la velocidad con la que reaparece el apetito; al tener un aporte calórico y graso mayor, sostiene mejor el ayuno que el café solo.', false),
('ensalada-frutas', ARRAY['ensalada de frutas', 'frutas picadas', 'cocktail de frutas natural']::text[], 'Frescura viva, agua de vegetación, vitaminas y azúcares naturales (fructosa) acompañados de fibra vegetal directa.', 'Ideal para las mañanas calurosas de verano. Para evitar un pico brusco de fructosa en ayunas, sumale unas cucharadas de yogur griego o semillas al plato; la proteína y la grasa ralentizan la absorción del azúcar de la fruta. Tip extra: un chorrito de jugo de limón fresco evita que la fruta se oxide y realza los sabores tropicales.', 'Registra la ligereza y el confort hidratante; vas a sentir el cuerpo sumamente liviano y activo para arrancar el día con vitalidad.', false),
('factura-crema', ARRAY['factura con crema', 'vigilante', 'tortita negra con crema', 'medialuna rellena']::text[], 'Pieza de bollería compleja que suma a la masa base un relleno untuoso de crema pastelera o dulce de leche. Explosión dulce y calórica.', 'Funciona como un gusto excepcional de fin de semana. Al tener crema o dulce, la carga de azúcar simple es masiva. Tip extra: acompáñala obligatoriamente con un café o mate bien amargo para cortar el dulzor empalagoso.', 'Presta atención al pico de energía y posterior bajón; este tipo de productos exige movimiento físico posterior para quemar el excedente de glucosa de golpe.', false),
('galleta-agua', ARRAY['galleta de agua', 'galletitas de agua', 'galletas de grasa', 'galletitas saladas', 'criollitas']::text[], 'Clásico acompañamiento seco de almacén. Harina refinada, agua y grasas vegetales o animales en formato crujiente y de fácil conservación.', 'No te dejes engañar por su liviandad visual: nutricionalmente son carbohidratos refinados secos. Si las usás para desayunar, untales algo de proteína (huevo, queso) para armar un desayuno real. Tip extra: masticá con conciencia y acompañalas con abundante líquido para evitar la sequedad estomacal.', 'Evalúa tu saciedad; al ser un producto aireado y seco, es muy fácil comer de más sin notar el volumen calórico real.', false),
('galletas-semoladas', ARRAY['galletas semoladas', 'galletitas semoladas', 'galletas de sémola']::text[], 'Clásicas galletas regionales de textura arenosa y suave, elaboradas con sémola de trigo y grasas. Sabor dulce y reconfortante.', 'Ideales para una pausa con el mate o el té, pero tratá de racionarlas ya que su perfil de azúcares y harinas refinadas dispara rápido la energía. Tip extra: disfrutalas despacio, una a una, para saciar el antojo dulce sin necesidad de devorar medio paquete.', 'Registra el nivel de saciedad; al ser dulces y secas, pueden generar un falso disparador de apetito si se comen sin atención.', false),
('huevo-revuelto', ARRAY['huevo revuelto', 'huevos revueltos', 'revuelto de huevos', 'omelette matutino']::text[], 'Fuente suprema de proteína completa, colina y grasas de altísima calidad biológica para despertar el cerebro y la masa muscular.', 'Cocinalos a fuego muy bajo con un toque mínimo de manteca o aceite de oliva para que queden cremosos y no se sequen. Tip extra: una pizca de pimienta negra y ciboulette picada arriba elevan el plato a nivel de restaurante top.', 'Compara tu saciedad matutina frente a cualquier desayuno basado en harinas; el huevo es el rey indiscutido para llegar al almuerzo sin acordarte de la comida.', false),
('leche', ARRAY['leche', 'leche entera', 'leche descremada', 'taza de leche']::text[], 'Alimento líquido completo que aporta proteínas de alta calidad (caseína y suero), calcio y azúcares naturales (lactosa).', 'Si la lactosa te suele caer pesada o te hincha, opta por versiones deslactosadas o probá con bebidas vegetales de buena calidad. Tip extra: un toque de cacao amargo o una pizca de canela mejora la palatabilidad y facilita su digestión.', 'Presta atención a tu comodidad abdominal tras consumirla; una buena digestión láctea debe sentirse liviana y sin gases.', false),
('leche-chocolatada', ARRAY['leche chocolatada', 'chocolatada', 'cacao con leche']::text[], 'Bebida ultra reconfortante de alta densidad energética. Combina los azúcares y grasas de la leche con el estímulo del cacao y el azúcar añadido.', 'Preparala en casa usando cacao amargo real con un toque de azúcar mascabo o edulcorante, evitando los cartones industriales saturados de jarabe de maíz. Tip extra: una pizca mínima de sal marina realza el sabor a chocolate de forma increíble.', 'Evalúa tu nivel de energía inmediata; al tener un índice glucémico alto, da un envión rápido pero puede generar un bajón posterior si no hay alimentos sólidos acompañando.', false),
('mate-cocido', ARRAY['mate cocido', 'mate cocido de saquito', 'yerba cocida']::text[], 'Infusión tradicional a base de yerba mate. Aporta antioxidantes, una dosis limpia de energía y un perfil sumamente reconfortante para arrancar el día.', 'Endulzarlo con estevia natural o tomarlo sin azúcar evita el choque glucémico matutino que te deja con hambre al rato. Tip extra: si lo preparás con leche en lugar de agua (mate cocido con leche), sumas un buen aporte proteico y de saciedad.', 'Nota la estabilidad de tu energía matutina; a diferencia del café fuerte, suele dar una activación más pausada y continua.', false),
('medialunas', ARRAY['medialunas', 'medialunas de manteca', 'medialunas de grasa', 'croissants']::text[], 'El rey indiscutido del desayuno argentino. Hojaldre fino con manteca o grasa, azúcar y un toque de almíbar. Placer supremo y densidad calórica elevada.', 'El gran clásico del fin de semana o el permitido laboral. Si querés un hack inteligente: comete una sola medialuna disfrutándola al 100% y acompañala con un buen revuelto de huevos o infusión sin azúcar para equilibrar el desayuno. Tip extra: las de manteca de buena calidad tienen mejor tolerancia digestiva que las industriales baratas cargadas de margarinas hidrogenadas.', 'Evalúa tu energía y tu humor matutino; te dan un golpe de dopamina y felicidad instantánea, pero vigilá que no te tiren modorra a las dos horas.', false),
('palta', ARRAY['palta', 'aguacate', 'tostada con palta']::text[], 'El rey de las grasas saludables matutinas. Aporta ácidos grasos monoinsaturados, fibra, potasio y una textura cremosa incomparable.', 'El bio-hack por excelencia de la mañana: pisá media palta sobre una tostada de masa madre con unas gotitas de limón y sal marina. Esa combinación de grasas buenas frena el hambre por horas y da un foco mental brillante. Tip extra: sumale un huevo poche o revuelto arriba para armar el desayuno proteico perfecto.', 'Nota la estabilidad absoluta de tu energía y la ausencia total de ansiedad por comer a media mañana; las grasas saludables son el mejor combustible matutino.', false),
('te', ARRAY['te', 'té', 'te negro', 'te verde', 'infusión de te']::text[], 'Bebida milenaria rica en antioxidantes. Dependiendo de la variedad, aporta una dosis moderada de teína para una activación sutil y sostenida.', 'No dejes infusionar el té negro demasiado tiempo si te cae pesado al estómago (evitá que se ponga amargo y astringente). Tip extra: un chorrito de limón en el té verde o negro potencia la absorción de sus antioxidantes naturales.', 'Analiza tu confort digestivo; es una alternativa sumamente amable para hidratar y acompañar la mañana sin sobrecargar el sistema gástrico.', false),
('torta-criollitos', ARRAY['torta', 'tortitas', 'criollitos', 'bizcochitos de grasa criollos', 'tortas cordobesas']::text[], 'Pieza de panadería tradicional a base de harina refinada y alta carga de grasa animal o vegetal. Textura hojaldrada y sabor irresistible.', 'Son una bomba calórica y lipídica de consumo ocasional; si te vas a dar el gusto, acompañalos con un buen mate amargo para equilibrar la pesadez. Tip extra: no los comas como desayuno diario si buscás rendimiento mental despejado, ya que exigen mucha energía gástrica.', 'Registra la modorra o pesadez posterior; las harinas con grasa de cocción pesada suelen desacelerar la agilidad matutina.', false),
('tostada-masa-madre', ARRAY['tostada masa madre', 'pan de masa madre tostado', 'tostada de campo']::text[], 'La joya de la panadería moderna. Fermentación larga y natural con levaduras salvajes que predigieren el gluten y reducen drásticamente el impacto glucémico.', 'El gran hack de bio-hacking matutino: la masa madre es infinitamente más amigable para el intestino que cualquier pan industrial. Tostada con aceite de oliva y tomate es un manjar de dioses. Tip extra: la acidez natural de la fermentación mejora la absorción de los minerales del pan.', 'Analiza tu comodidad abdominal; la ausencia de químicos y la predigestión hacen que no te genere la típica hinchazón matutina de las harinas comunes.', false),
('tostada-pan-blanco', ARRAY['tostada pan blanco', 'tostadas de pan lactal blanco', 'pan tostado blanco']::text[], 'El clásico pan de molde industrial tostado. Aporta carbohidratos simples listos para ser absorbidos rápidamente por el organismo.', 'Tostarlo reduce levemente el impacto glucémico inmediato en comparación con el pan fresco, pero sigue siendo harina refinada. Tip extra: sumale una fuente de proteína firme arriba (como un huevo revuelto) para transformar un carbohidrato simple en un desayuno completo.', 'Nota la velocidad con la que se digiere; es un desayuno liviano pero de corta duración en cuanto a la saciedad.', false),
('tostada-pan-integral', ARRAY['tostada pan integral', 'pan integral real', 'tostadas integrales']::text[], 'Panificado elaborado con harina 100% de grano entero, conservando el germen y la fibra del cereal para una energía más estable.', 'Excelente opción para arrancar el día si se combina con grasas saludables o proteínas. Tip extra: untale queso crema descremado y un toque de semillas de sésamo o chía para completar el perfil nutricional.', 'Registra la estabilidad de tu energía; vas a notar que el hambre tarda mucho más en aparecer en comparación con el pan blanco refinado.', false),
('tostada-pan-salvado', ARRAY['tostada pan salvado', 'pan negro', 'tostadas de pan integral industrial', 'pan de salvado']::text[], 'Versión de molde con agregado de salvado de trigo. Aporta un poco más de fibra insoluble que el pan blanco convencional.', 'Ojo con el marketing del color: muchos panes negros industriales son solo pan blanco teñido con caramelo. Buscá los que tengan textura densa y real presencia de semillas. Tip extra: un toque de palta pisada y sal marina arriba convierte la tostada en un caballito de batalla fit excelente.', 'Compara tu saciedad con el pan blanco; la fibra extra del salvado ayuda a mejorar levemente el tránsito matutino.', false),
('yogurt', ARRAY['yogurt', 'yogur', 'yogur firme', 'yogur bebible']::text[], 'Lácteo fermentado rico en probióticos vivos que cuidan tu microbiota intestinal, aportando proteínas de fácil asimilación y calcio.', 'Elegí versiones naturales o sin azúcares agregados en exceso (leete las etiquetas); si es muy ácido, endulzalo con unas gotitas de estevia o fruta fresca. Tip extra: sumarle unas cucharadas de semillas o frutos secos transforma el yogur en un desayuno con saciedad real.', 'Nota cómo responde tu tránsito intestinal; los fermentos lácteos bien tolerados mejoran notablemente la liviandad abdominal.', false),
('yogurt-griego', ARRAY['yogurt griego', 'yogur griego', 'yogur estilo griego']::text[], 'Versión colada del yogur tradicional. Mucho más espeso, con el doble de concentración de proteínas y menor cantidad de suero y lactosa.', 'Es un verdadero superalimento matutino por su alto poder saciante. Usalo como base y sumale frutas o frutos secos. Tip extra: un hilito de aceite de oliva o frutos secos tostados arriba le da un toque gourmet brutal si lo preferís salado (estilo dip mediterráneo).', 'Compara el tiempo que lográs estar sin hambre en comparación con el yogur común; el aporte proteico del yogur griego frena el apetito por horas.', false)
